// ══════════════════════════════════════════════════════════════
// NODO 2: Validador de Archivo + Cálculo MD5
// ══════════════════════════════════════════════════════════════
const crypto = require('crypto');

const item = $input.item;
const json = item.json;

// 1. Detectar adjunto
const attachmentKey = Object.keys(item.binary ?? {}).find(k => k.startsWith('attachment'));
if (!attachmentKey) {
  throw new Error('NO_ATTACHMENT: El correo no contiene adjuntos.');
}

const binaryMeta = item.binary[attachmentKey];
const fileName   = binaryMeta.fileName ?? binaryMeta.name ?? 'unknown.csv';
const mimeType   = binaryMeta.mimeType ?? '';

// 2. Validar extensión
const allowedExt = ['.csv', '.txt', '.tsv'];
const ext = fileName.slice(fileName.lastIndexOf('.')).toLowerCase();
if (!allowedExt.includes(ext)) {
  throw new Error(`INVALID_FORMAT: Extensión no soportada: ${ext}. Permitidos: ${allowedExt.join(', ')}`);
}

// 3. Leer datos binarios y calcular MD5
const binaryData = binaryMeta.data ?? '';
const buffer     = Buffer.from(binaryData, 'base64');
const md5Hash    = crypto.createHash('md5').update(buffer).digest('hex');

// 4. Validar tamaño (máx 10 MB)
const MAX_BYTES = 10 * 1024 * 1024;
if (buffer.length > MAX_BYTES) {
  throw new Error(`FILE_TOO_LARGE: Archivo ${fileName} pesa ${(buffer.length/1024/1024).toFixed(2)}MB. Máximo permitido: 10MB.`);
}

// 5. Convertir binario a texto UTF-8
const rawText = buffer.toString('utf-8');

return [{
  json: {
    fileName,
    mimeType,
    fileSize:      buffer.length,
    md5Hash,
    rawText,
    binaryKey:     attachmentKey,
    gmailMessageId: json.id ?? json.messageId ?? '',
    gmailFrom:     json.from ?? '',
    gmailSubject:  json.subject ?? '',
    receivedAt:    new Date().toISOString(),
    // Campos para query PG (se usan en nodo Postgres siguiente)
    queryFileName: fileName,
    queryMd5:      md5Hash,
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 4: Verificar Config + Duplicados
// ══════════════════════════════════════════════════════════════
const pgResult = $input.item.json;

// Si no hay resultado de PG, el archivo no tiene config
if (!pgResult.archivo_id) {
  throw new Error(`NO_CONFIG: El archivo '${$('JS — Validador + MD5').item.json.fileName}' no coincide con ningún patron_nombre en etl_config.`);
}

// Si ya fue procesado con éxito (MD5 duplicado)
if (pgResult.prev_log_id && pgResult.prev_status === 'SUCCESS') {
  throw new Error(`DUPLICATE: El archivo ya fue procesado exitosamente (log_id=${pgResult.prev_log_id}). MD5: ${$('JS — Validador + MD5').item.json.md5Hash}`);
}

// Recuperar datos del nodo validador
const validatorData = $('JS — Validador + MD5').item.json;

return [{
  json: {
    ...validatorData,
    etlConfig: {
      archivo_id:       pgResult.archivo_id,
      patron_nombre:    pgResult.patron_nombre,
      tabla_destino:    pgResult.tabla_destino,
      esquema_destino:  pgResult.esquema_destino ?? 'public',
      mapping_columnas: typeof pgResult.mapping_columnas === 'string'
                          ? JSON.parse(pgResult.mapping_columnas)
                          : pgResult.mapping_columnas,
      columnas_clave:   pgResult.columnas_clave,
      delimitador:      pgResult.delimitador ?? null,
    }
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 6: Parser Universal CSV
// Detecta delimitador, elimina BOM, parsea a array de objetos
// ══════════════════════════════════════════════════════════════

const logId     = $input.item.json.log_id;
const prevData  = $('JS — Verificar Config + Duplicados').item.json;
const rawText   = prevData.rawText;
const etlConfig = prevData.etlConfig;

// ── 1. Eliminar BOM UTF-8 ─────────────────────────────────────
const cleanText = rawText.replace(/^\uFEFF/, '');

// ── 2. Auto-detectar delimitador ─────────────────────────────
function detectDelimiter(sample, forced) {
  if (forced) return forced;
  const firstLine = sample.split('\n')[0];
  const commas     = (firstLine.match(/,/g)  ?? []).length;
  const semicolons = (firstLine.match(/;/g)  ?? []).length;
  const tabs       = (firstLine.match(/\t/g) ?? []).length;
  if (tabs > commas && tabs > semicolons) return '\t';
  return semicolons > commas ? ';' : ',';
}

// ── 3. Parser CSV robusto (maneja comillas y saltos internos) ─
function splitLine(line, delim) {
  const result = [];
  let cur = '', inQuote = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; }
    else if (ch === '"')  { inQuote = !inQuote; }
    else if (ch === delim && !inQuote) { result.push(cur); cur = ''; }
    else { cur += ch; }
  }
  result.push(cur);
  return result;
}

function parseCSV(text, delim) {
  const lines   = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
  const headers = splitLine(lines[0], delim).map(h => h.trim().replace(/^"|"$/g, ''));
  const records = [];

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const values = splitLine(line, delim);
    if (values.every(v => !v.trim())) continue;

    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = (values[idx] ?? '').trim().replace(/^"|"$/g, '');
    });
    records.push(obj);
  }
  return { headers, records };
}

// ── 4. Ejecutar parseo ────────────────────────────────────────
const delim  = detectDelimiter(cleanText, etlConfig.delimitador);
const parsed = parseCSV(cleanText, delim);

if (!parsed.records.length) {
  throw new Error(`EMPTY_FILE: El archivo '${prevData.fileName}' no contiene filas de datos.`);
}

return [{
  json: {
    ...prevData,
    logId:      logId,
    delimiter:  delim,
    totalRows:  parsed.records.length,
    csvHeaders: parsed.headers,
    records:    parsed.records,
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 7: Limpiador de Datos Dinámico
// Aplica mapping, trim, normaliza monedas y fechas
// ══════════════════════════════════════════════════════════════

const { records, etlConfig, logId, md5Hash, fileName } = $input.item.json;
const mapping = etlConfig.mapping_columnas;

// ── Helpers ───────────────────────────────────────────────────

function parseCurrency(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  let str = String(raw).trim();
  // Negativo entre paréntesis: (1.234,56) → -1234.56
  const isNegative = /^\(.*\)$/.test(str);
  if (isNegative) str = str.replace(/[()]/g, '').trim();
  // Eliminar símbolo de moneda y espacios
  str = str.replace(/[$€£¥Bs\.\s]/g, ' ').trim();
  // Reemplazar espacios usados como separador de miles
  str = str.replace(/ /g, '');
  // Formato europeo: 1.234,56
  const hasEuroFormat = /\d\.\d{3}/.test(str) && str.includes(',');
  if (hasEuroFormat) {
    str = str.replace(/\./g, '').replace(',', '.');
  } else {
    str = str.replace(/,/g, '');
  }
  const num = parseFloat(str);
  if (isNaN(num)) return null;
  return isNegative ? -Math.abs(num) : num;
}

function parseDate(raw) {
  if (!raw) return null;
  const str = String(raw).trim();
  // ISO ya correcto
  if (/^\d{4}-\d{2}-\d{2}/.test(str)) return str.slice(0, 10);
  // DD/MM/YYYY o DD-MM-YYYY
  const dmy = str.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if (dmy) return `${dmy[3]}-${dmy[2].padStart(2,'0')}-${dmy[1].padStart(2,'0')}`;
  // MM/DD/YYYY (formato US)
  const mdy = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (mdy) {
    const year = mdy[3].length === 2 ? '20' + mdy[3] : mdy[3];
    const d = new Date(`${year}-${mdy[1].padStart(2,'0')}-${mdy[2].padStart(2,'0')}`);
    if (!isNaN(d)) return d.toISOString().slice(0, 10);
  }
  // YYYYMM (periodo)
  if (/^\d{6}$/.test(str)) return `${str.slice(0,4)}-${str.slice(4,6)}-01`;
  // Fallback nativo
  const d = new Date(str);
  if (!isNaN(d)) return d.toISOString().slice(0, 10);
  return null;
}

function looksLikeNumber(val) {
  return /^-?[\d.,()\s$€£¥Bs]+$/.test(String(val).trim());
}

function looksLikeDate(colName) {
  return /fecha|date|fec|periodo|period|dt_/i.test(colName);
}

// ── Procesamiento ─────────────────────────────────────────────
const cleaned  = [];
const rejected = [];

for (let i = 0; i < records.length; i++) {
  const raw = records[i];
  const out = {};

  try {
    for (const [csvCol, dbCol] of Object.entries(mapping)) {
      let val = raw[csvCol];
      if (val === undefined) continue;

      val = String(val ?? '').trim();

      // Null semántico
      if (['', 'NULL', 'null', 'N/A', 'n/a', 'NA', '-', 'undefined'].includes(val)) {
        out[dbCol] = null;
        continue;
      }

      // Fechas (prioridad sobre número para evitar parsear timestamps)
      if (looksLikeDate(csvCol) || looksLikeDate(dbCol)) {
        out[dbCol] = parseDate(val);
        continue;
      }

      // Monedas / números
      if (looksLikeNumber(val)) {
        out[dbCol] = parseCurrency(val);
        continue;
      }

      // Booleanos
      if (/^(true|false|si|no|yes|1|0)$/i.test(val)) {
        out[dbCol] = /^(true|si|yes|1)$/i.test(val);
        continue;
      }

      // Texto plano
      out[dbCol] = val;
    }

    // Metadatos de auditoría
    out._etl_log_id    = logId;
    out._etl_md5       = md5Hash;
    out._etl_loaded_at = new Date().toISOString();

    cleaned.push(out);

  } catch (err) {
    rejected.push({
      log_id:       logId,
      tabla_destino: etlConfig.tabla_destino,
      fila_numero:  i + 2,
      fila_raw:     JSON.stringify(raw),
      motivo_error: err.message,
    });
  }
}

return [{
  json: {
    ...($input.item.json),
    cleanedRecords:  cleaned,
    rejectedRecords: rejected,
    totalCleaned:    cleaned.length,
    totalRejected:   rejected.length,
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 8: Generador de UPSERT Dinámico por Lotes
// Construye queries SQL con BEGIN/COMMIT por lote de 100 filas
// ══════════════════════════════════════════════════════════════

const { cleanedRecords, etlConfig, logId } = $input.item.json;
const BATCH_SIZE = 100;

const tabla      = `"${etlConfig.esquema_destino}"."${etlConfig.tabla_destino}"`;
const keyColumns = etlConfig.columnas_clave;

function buildUpsertQuery(batch, tabla, keyColumns) {
  if (!batch.length) return null;

  const allCols   = Object.keys(batch[0]).filter(c => !c.startsWith('_etl_'));
  const auditCols = ['_etl_log_id', '_etl_md5', '_etl_loaded_at'];
  const fullCols  = [...allCols, ...auditCols];

  // Columnas que se actualizan en CONFLICT
  const updateCols = allCols.filter(c => !keyColumns.includes(c));

  // Generar VALUE placeholders
  let paramIndex = 1;
  const valuePlaceholders = batch.map(row => {
    const ph = fullCols.map(() => `$${paramIndex++}`).join(', ');
    return `(${ph})`;
  }).join(',\n    ');

  // Valores aplanados
  const flatValues = batch.flatMap(row =>
    fullCols.map(c => (row[c] !== undefined ? row[c] : null))
  );

  // SET clause
  const auditSet  = `_etl_log_id = EXCLUDED._etl_log_id, _etl_loaded_at = EXCLUDED._etl_loaded_at`;
  const dataSet   = updateCols.map(c => `"${c}" = EXCLUDED."${c}"`).join(',\n      ');
  const setClause = updateCols.length ? `${dataSet},\n      ${auditSet}` : auditSet;

  const colList  = fullCols.map(c => `"${c}"`).join(', ');
  const keyList  = keyColumns.map(c => `"${c}"`).join(', ');

  const sql = `BEGIN;\nINSERT INTO ${tabla} (${colList})\nVALUES\n    ${valuePlaceholders}\nON CONFLICT (${keyList})\nDO UPDATE SET\n    ${setClause};\nCOMMIT;`;

  return { sql, values: flatValues, count: batch.length };
}

// Dividir en lotes
const batches = [];
for (let i = 0; i < cleanedRecords.length; i += BATCH_SIZE) {
  batches.push(cleanedRecords.slice(i, i + BATCH_SIZE));
}

const queries = batches
  .map(b => buildUpsertQuery(b, tabla, keyColumns))
  .filter(Boolean)
  .map((q, i) => ({ ...q, batchIndex: i + 1, totalBatches: batches.length }));

return [{
  json: {
    ...($input.item.json),
    upsertQueries: queries,
    totalBatches:  queries.length,
    currentBatch:  0,
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 9: Splitter de Lotes
// Convierte el array de queries en ítems individuales para
// que el nodo Postgres los ejecute en un loop
// ══════════════════════════════════════════════════════════════

const data         = $input.item.json;
const upsertQueries = data.upsertQueries ?? [];

if (!upsertQueries.length) {
  throw new Error('NO_QUERIES: No se generaron queries de UPSERT. Verifique cleanedRecords.');
}

// Emitir un ítem por cada lote
return upsertQueries.map(q => ({
  json: {
    // Contexto completo para el nodo PG
    batchSql:     q.sql,
    batchValues:  q.values,
    batchCount:   q.count,
    batchIndex:   q.batchIndex,
    totalBatches: q.totalBatches,
    // Contexto heredado
    logId:        data.logId,
    fileName:     data.fileName,
    md5Hash:      data.md5Hash,
    totalCleaned: data.totalCleaned,
    totalRejected: data.totalRejected,
    rejectedRecords: data.rejectedRecords,
    etlConfig:    data.etlConfig,
    gmailMessageId: data.gmailMessageId,
  }
}));

// ══════════════════════════════════════════════════════════════
// NODO 11: Agregador de Resultados
// Consolida todos los lotes procesados en un único resumen
// ══════════════════════════════════════════════════════════════

const allItems = $input.all();

if (!allItems.length) {
  throw new Error('AGGREGATE_ERROR: No hay ítems para agregar.');
}

// Tomar metadatos del primer ítem
const first = allItems[0].json;

// Contar totales
const totalOk    = allItems.reduce((acc, it) => acc + (it.json.batchCount ?? 0), 0);
const logId      = first.logId;
const fileName   = first.fileName;
const etlConfig  = first.etlConfig;
const rejectedRecords = first.rejectedRecords ?? [];
const totalRejected   = first.totalRejected ?? 0;
const gmailMessageId  = first.gmailMessageId ?? '';

return [{
  json: {
    logId,
    fileName,
    etlConfig,
    gmailMessageId,
    totalOk,
    totalRejected,
    rejectedRecords,
    batchesProcessed: allItems.length,
    status: 'SUCCESS',
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 13: Insertar Filas Rechazadas (si hay)
// ══════════════════════════════════════════════════════════════

const { rejectedRecords, logId, etlConfig } = $input.item.json;

if (!rejectedRecords || !rejectedRecords.length) {
  return [{ json: { rejectedInserted: 0, skipped: true } }];
}

// Construir INSERT batch de rechazados
let paramIdx = 1;
const placeholders = rejectedRecords.map(() => {
  return `($${paramIdx++}, $${paramIdx++}, $${paramIdx++}, $${paramIdx++}::jsonb, $${paramIdx++})`;
}).join(', ');

const values = rejectedRecords.flatMap(r => [
  logId,
  etlConfig?.tabla_destino ?? 'unknown',
  r.fila_numero,
  typeof r.fila_raw === 'string' ? r.fila_raw : JSON.stringify(r.fila_raw),
  r.motivo_error ?? 'Error desconocido',
]);

const sql = `INSERT INTO etl_rejected (log_id, tabla_destino, fila_numero, fila_raw, motivo_error) VALUES ${placeholders}`;

return [{
  json: {
    rejectedSQL:    sql,
    rejectedValues: values,
    rejectedCount:  rejectedRecords.length,
    logId,
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO 15: Gestión de Labels Gmail
// Mueve el correo a la carpeta correcta según resultado
// ══════════════════════════════════════════════════════════════

// Este nodo puede venir de SUCCESS o de ERROR
// Detectar origen por presencia de campos
const json = $input.item.json;

const status = json.status ?? 'ERROR';
const gmailMessageId = json.gmailMessageId ?? '';

const LABELS = {
  SUCCESS:   'etl/processed',
  ERROR:     'etl/rejected',
  DUPLICADO: 'etl/duplicates',
  NO_CONFIG: 'etl/unrecognized',
  RUNNING:   'etl/processing',
};

// Detectar tipo de error para categorizar mejor
let labelKey = status;
if (status === 'ERROR') {
  const msg = json.errorMessage ?? '';
  if (msg.includes('DUPLICATE'))  labelKey = 'DUPLICADO';
  if (msg.includes('NO_CONFIG'))  labelKey = 'NO_CONFIG';
}

const addLabel    = LABELS[labelKey] ?? LABELS.ERROR;
const removeLabel = 'INBOX';

return [{
  json: {
    gmailMessageId,
    addLabel,
    removeLabel,
    status,
    processedAt: new Date().toISOString(),
    summary: {
      fileName:     json.fileName ?? 'unknown',
      totalOk:      json.totalOk ?? 0,
      totalRejected: json.totalRejected ?? 0,
      logId:        json.logId ?? null,
    }
  }
}];

// ══════════════════════════════════════════════════════════════
// NODO ERROR: Manejador Global de Errores con ROLLBACK
// Conectar al output de error de cualquier nodo crítico
// ══════════════════════════════════════════════════════════════

const errorItem  = $input.item;
const errorMsg   = errorItem.json.error?.message ?? errorItem.json.message ?? 'Error desconocido';
const errorNode  = errorItem.json.error?.node ?? 'unknown';

// Intentar recuperar logId y contexto de nodos anteriores
let logId       = null;
let fileName    = 'unknown';
let gmailMsgId  = '';
let statusCode  = 'ERROR';

try {
  const validatorData = $('JS — Validador + MD5').item?.json;
  fileName   = validatorData?.fileName   ?? fileName;
  gmailMsgId = validatorData?.gmailMessageId ?? '';
} catch (_) {}

try {
  const logData = $('PG — Iniciar Log ETL').item?.json;
  logId = logData?.log_id ?? null;
} catch (_) {}

// Detectar tipo de error
if (errorMsg.includes('DUPLICATE')) statusCode = 'DUPLICADO';
if (errorMsg.includes('NO_CONFIG')) statusCode = 'NO_CONFIG';

const rollbackSQL = logId
  ? `ROLLBACK; UPDATE etl_logs SET status='ERROR', mensaje_error=$1, finalizado_en=NOW() WHERE log_id=$2;`
  : `ROLLBACK;`;

const rollbackValues = logId
  ? [`[${errorNode}] ${errorMsg}`, logId]
  : [];

return [{
  json: {
    rollbackSQL,
    rollbackValues,
    logId,
    fileName,
    gmailMessageId: gmailMsgId,
    status:         statusCode,
    errorMessage:   errorMsg,
    errorNode,
    failedAt:       new Date().toISOString(),
  }
}];

// Redirigir al Gmail Label Manager desde el flujo de error
const json = $input.item.json;
return [{ json }];
